local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["130cd681b412b212"] = { "Miserabile!", "." },
  ["131a6e7c4a418d33"] = { "Certo che non ho io il frammento. Sarebbe da idioti. Cammino tra selvaggi in questa terra maledetta! Non riesco a fare cinque passi senza che un orco o un umano impazzito cerchi di piantarmi un bastone appuntito nella pelle. In qualsiasi momento potresti benissimo trovarti a parlare con il mio spirito.\n\nComunque... l'ho nascosto.\n\nAvanti... chiedimi dove.", "." },
  ["131ee5d57d439074"] = { "Noi, suoi servitori giurati, eseguiamo i suoi ordini e imponiamo il suo dominio di ferro. Separato dalle energie del suo regno infuocato, Ragnaros non è che l'ombra di se stesso. Tuttavia, ha forza più che sufficiente per porre fine alla tua vita.", "." },
  ["13232029bfec7c82"] = { "Sono Muln Earthfury del Circolo della Terra. Cosa ti porta da me oggi?", "." },
  ["1324ba9129c147ed"] = { "Studio gli elementi noti e ignoti del nostro mondo.", "." },
  ["132ec40895521ca8"] = { "Sono anni che non ragiono con il cuore, ma ora sta tornando tutto a galla.", "." },
  ["1338397e0c767a0a"] = { "Preparati a incontrare il tuo creatore.", "." },
  ["133befce7419ec0a"] = { "Grazie, {name}. Ti ricorderò per sempre. Troverai il mio forziere nel mio accampamento, a nord di ⟦Stonard=Pietrachiusa⟧.", "." },
  ["133d2af43f06860a"] = { "Quei bastardi ci sono piombati addosso di notte, dopo che avevamo bevuto qualche bicchiere. Altrimenti li avremmo fatti a pezzi, puoi contarci.\n\nAdesso sono tutti morti... tranne pochi di noi.", "." },
  ["134515cfa4450473"] = { "Il ⟦Ragefire Chasm=Baratro di Fiamma Furente⟧ si trova sotto la Shadow Cleft, al centro di Orgrimmar.", "." },
  ["134852a7764925dc"] = { "Enu thora'serador. Questo è un luogo sacro.", "." },
  ["1349d1e382bdc388"] = { "Ti sembro una guida? E va bene, cosa ti serve?", "." },
  ["134c7661460ca085"] = { "Tempi duri, eh, {name}? Ovunque ti giri c'è qualcuno che ha bisogno d'aiuto, e io e mia moglie non facciamo eccezione.", "." },
  ["13507331cc3597fc"] = { "Questi nani sono gli stessi di oggi, giusto? I nani mantengono altri legami con i Terrigeni?", "." },
  ["1355ea4c90bc60c4"] = { "Salute, {name}.", "." },
  ["135a847417fad321"] = { "Non lo accetterò! Io servo la Luce!", "." },
  ["135b53bf12ddc50d"] = { "Forse posso insegnarti qualcosa...", "." },
  ["135f64029e899fde"] = { "Non mi tirerete mai fuori dal mio bunker, infedeli!", "." },
  ["13604dcc337c10d7"] = { "Ho perso il mio ⟦Signet of Unyielding Strength=Sigillo della Forza Inflessibile⟧. Puoi sostituirmelo?", "." },
  ["1365dd61c585eb20"] = { "Il ⟦Snowfall Graveyard=Cimitero di Nevealta⟧ si trova in cima a una collina nel ⟦Field of Strife=Pian della Discordia⟧, a est del ⟦Winterax Hold=Covo degli Asciafredda⟧.\n\nAl momento è sotto il controllo dell'⟦Alliance=Alleanza⟧.", "." },
  ["13687dd2f816099c"] = { "In base al campione di tossina che ci hai fornito, pensiamo che ti servirà quanto segue: un Accelerante Arcano, quattro Risonatori Ectoplasmici e quattro pezze di telarunica. Con il Focalizzatore Vitreo al seguito, procurati i risonatori dagli spettri e dai non morti spettrali qui nelle ⟦Plaguelands=Terre Infette⟧!\n\nQuando avrai questi oggetti, dovresti riuscire a caricare l'antidoto in quel calderone.", "." },
  ["137f1feaf98cec95"] = { "Banchetterò con le tue ossa!", "." },
  ["138840e7d893eb81"] = { "Ho abbastanza rifornimenti per promuovere le nostre truppe a esperte.", "." },
  ["13937a6223caf32e"] = { "Salve, Eitrigg. Porto notizie dai ⟦Blackrock Spire=Bastioni di Roccianera⟧.", "." },
  ["1394f37b3c195982"] = { "La professione dell'Incantamento mostra il ciclo di distruzione e creazione che sta al cuore della natura. Teg, alla Dawnstrider Enchanters sull'altura di mezzo, ti mostrerà come.", "." },
  ["1396a7093460e1c4"] = { "Anche se in qualche modo riuscissi a liberarci senza sconfiggere ⟦C'Thun=C'thun⟧, concentreremmo tutti i nostri poteri per ricacciare la bestia nell'inferno da cui è venuta, A QUALUNQUE COSTO.", "." },
  ["139b8a3314f9be51"] = { "⟦Icy Scale Gauntlets=Guanti Lunghi di Scaglie Ghiacciate⟧.", "." },
  ["139ff695d720382b"] = { "Là fuori nel buio si annidano molte cose, e oggi la luce serve più che mai. Se solo queste povere anime capissero che, anche se il nostro mondo è cambiato, non dobbiamo per forza essere i mostri che i vivi credono che siamo.", "." },
  ["13a4cdca92b47d61"] = { "Non bastò.\n\n<Fairbanks fa un breve sorrisetto, perso in un ricordo.>\n\nNe vennero mille e mille morirono. Per la Luce! Per la potenza di Mograine! Li abbatteva alla velocità con cui arrivavano. In mezzo al caos, notai che il Mograine minore era ancora lì, in lontananza. Lo chiamai: \"Aiutaci, Renault! Aiuta tuo padre, ragazzo!\"", "." },
  ["13a7662899e2b67e"] = { "Hai finito il compito di ieri? Se sì, siediti accanto a me!", "." },
  ["13adfa09cfc6ae15"] = { "Ho quasi finito, {name}. Ancora qualche ritocco!", "." },
  ["13b04365966fb2e0"] = { "⟦Blackrock Depths=Sotterranei di Roccianera⟧", "." },
  ["13b137b6e80e423c"] = { "Domani inizieremo l'addestramento dei nostri draghi più promettenti, quindi non dimenticate i giocattoli da masticare.", "." },
  ["13b24ae989bfe1e5"] = { "I tuoi occhi diventeranno dei graziosi ninnoli!", "." },
  ["13b2a12dedbb890d"] = { "<Benvenuto/Benvenuta> alla promozione estiva iCoke-WOW.\n\n<Caro/Cara> {name}, l'aureola della dea della fortuna risplende su di te. Obbedisci all'ordine del dio e riceverai un regalo speciale e misterioso. Ora il portale di Azeroth è aperto per te. Presto avrà inizio una grande avventura. Sei <pronto/pronta>?\n\nChe l'onore sia con te!", "." },
  ["13b479aab3b0a594"] = { "Ho quasi abbastanza rifornimenti per promuovere le truppe a unità campione.", "." },
  ["13b6178e03b12b89"] = { "Se riesci a completare un mazzo di carte delle Bestie, riceverai in premio una carta superiore, la Carta di Lunacupa: Drago Blu. È molto utile per ripristinare le energie magiche.", "." },
  ["13bb0c08a7677aaa"] = { "Gli invasori sono qui!", "." },
  ["13d263b0bf352233"] = { "Grazie, {name}! Per il ⟦Un'Goro Crater=Cratere di Un'Goro⟧ sei <un/una> <eroe/eroina>!", "." },
  ["13d4eff5e2f3da07"] = { "Finora ho avuto indulgenza con te, ma ora mi annoi. Ammira la magnificenza del mio potere, e dispera!", "." },
  ["13d869b4d1de584f"] = { "%s pungola il piccolo scoiattolo peloso con evidente delusione.", "." },
  ["13fb827df72d5ea4"] = { "La banca", "." },
  ["13ffbdcb74cc5349"] = { "Per la gloria del signore dei venti!", "." },
})
